"""Post-process an autogenerated Alembic revision for MySQL.

Autogenerate emits ``op.drop_index`` calls ahead of ``op.drop_table`` in
``downgrade()``.  MySQL refuses to drop an index that a foreign key relies on
(error 1553) and the table drop removes its indexes anyway, so we strip them.

Usage: python scripts/fix_downgrade.py services/<svc>/alembic/versions/<file>.py
"""

import re
import sys
from pathlib import Path

NOTE = ("    # Dropping a table drops its indexes; explicit drop_index calls are omitted because\n"
        "    # MySQL refuses to drop an index that a foreign key still depends on (error 1553).\n")

for name in sys.argv[1:]:
    path = Path(name)
    src = path.read_text()
    head, sep, tail = src.partition("def downgrade() -> None:\n")
    lines = [ln for ln in tail.splitlines(keepends=True)
             if not ln.strip().startswith(("op.drop_index", "# ### "))]
    path.write_text(head + sep + NOTE + "".join(lines))
    print(f"fixed {name}")
